int shmid;

// Attach R/W (shmaddr=NULL lets system choose address)
char *shm_ptr = (char *)shmat(shmid, NULL, 0);

if (shm_ptr == (void *)-1) {
    /* Handle error (check errno) */
}

// Example: Attach Read-Only
void *ro_ptr = shmat(shmid, NULL, SHM_RDONLY);

// Example: Attach at specific, page-aligned address (using SHM_RND flag)
const void *base_addr = (const void *)0x40000000;
void *specific_ptr = shmat(shmid, base_addr, SHM_RND);

